//! Actual native implicit-new argument-presence producer facts, not complete grammar proof.
//! SAME ParsedExpr owns this small DATA buffer; no source/model authority,
//! diagnostic-string parsing, alternate AST or cache is introduced.
use crate::{Span,SettingAdmission,SettingRootLease};
use std::{io,mem::size_of,sync::Arc};
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub struct OriginalConstructorFact{at:Span,has_args:bool}
impl OriginalConstructorFact{pub fn span(self)->Span{self.at}pub fn arguments_present(self)->bool{self.has_args}}
struct Payload{rows:Vec<OriginalConstructorFact>,credit:SettingRootLease}
#[derive(Default)]pub struct OriginalConstructorFacts(Option<Arc<Payload>>);
impl Clone for OriginalConstructorFacts{fn clone(&self)->Self{Self(self.0.as_ref().map(Arc::clone))}}
impl Drop for OriginalConstructorFacts{fn drop(&mut self){if let Some(owner)=self.0.take(){if let Some(payload)=Arc::into_inner(owner){drop(payload)}}}}
impl std::fmt::Debug for OriginalConstructorFacts{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{self.as_slice().fmt(f)}}
impl PartialEq for OriginalConstructorFacts{fn eq(&self,other:&Self)->bool{self.as_slice()==other.as_slice()}}impl Eq for OriginalConstructorFacts{}
impl OriginalConstructorFacts{pub fn implicit_at_using(&self,at:Span,a:&SettingAdmission<'_>)->io::Result<Option<bool>>{poll(a)?;if !self.is_admitted_by(a){return Err(io::ErrorKind::InvalidInput.into())}for row in self.as_slice(){poll(a)?;if row.at==at{return Ok(Some(row.has_args))}}Ok(None)}pub fn as_slice(&self)->&[OriginalConstructorFact]{self.0.as_ref().map_or(&[],|p|p.rows.as_slice())}pub fn is_admitted_by(&self,a:&SettingAdmission<'_>)->bool{self.0.as_ref().is_none_or(|p|a.matches_lease_domain(&p.credit))}pub fn visit_storage(&self,mut visit:impl FnMut(usize,usize,usize)){if let Some(p)=&self.0{let fixed=size_of::<Payload>()+2*size_of::<usize>();visit(Arc::as_ptr(p)as usize,fixed,fixed);if p.rows.capacity()!=0{visit(p.rows.as_ptr()as usize,p.rows.len()*size_of::<OriginalConstructorFact>(),p.rows.capacity()*size_of::<OriginalConstructorFact>());}p.credit.visit_counter_storage(|address,bytes|visit(address,bytes,bytes));}}}
#[derive(Default)]pub(crate) struct Builder{rows:Vec<OriginalConstructorFact>,credit:Option<SettingRootLease>}
fn poll(a:&SettingAdmission<'_>)->io::Result<()>{let result=a.checkpoint();if let Some(error)=a.take_operational_error(){return Err(error)}result}
impl Builder{pub fn push(&mut self,at:Span,has_args:bool,a:&SettingAdmission<'_>)->io::Result<()>{poll(a)?;if at.start>=at.end||self.rows.last().is_some_and(|row|row.at.start>=at.start){return Err(io::ErrorKind::InvalidInput.into())}if self.credit.is_none(){self.credit=Some(a.reserve(size_of::<Payload>()+2*size_of::<usize>()).map_err(|e|a.take_operational_error().unwrap_or(e))?);}let credit=self.credit.as_mut().unwrap();if !a.matches_lease_domain(credit){return Err(io::ErrorKind::InvalidInput.into())}if self.rows.len()==self.rows.capacity(){let count=self.rows.capacity().max(2).checked_mul(2).ok_or(io::ErrorKind::OutOfMemory)?;let peak=count.checked_mul(4).and_then(|n|n.checked_mul(size_of::<OriginalConstructorFact>())).ok_or(io::ErrorKind::OutOfMemory)?;let old=self.rows.capacity().checked_mul(size_of::<OriginalConstructorFact>()).ok_or(io::ErrorKind::OutOfMemory)?;a.grow(credit,peak).map_err(|e|a.take_operational_error().unwrap_or(e))?;self.rows.try_reserve_exact(count-self.rows.len()).map_err(|e|io::Error::new(io::ErrorKind::OutOfMemory,e))?;let actual=self.rows.capacity().checked_mul(size_of::<OriginalConstructorFact>()).ok_or(io::ErrorKind::OutOfMemory)?;if actual>peak{return Err(io::ErrorKind::OutOfMemory.into())}let free=old.checked_add(peak).and_then(|n|n.checked_sub(actual)).ok_or(io::ErrorKind::InvalidData)?;a.shrink(credit,free).map_err(|e|a.take_operational_error().unwrap_or(e))?;}self.rows.push(OriginalConstructorFact{at,has_args});poll(a)}pub fn finish(self)->OriginalConstructorFacts{match self.credit{Some(credit)=>OriginalConstructorFacts(Some(Arc::new(Payload{rows:self.rows,credit}))),None=>OriginalConstructorFacts(None)}}}

#[cfg(test)]mod tests{use super::*;use std::sync::{Arc, atomic::{Ordering}};
 #[test]fn actual_constructor_presence_rows_are_funded_alias_retained_and_foreign_lookup_refused(){let used=crate::SettingChargeCounter::try_new(crate::SettingChargeCounter::root_allocation_bytes()).unwrap();let a=SettingAdmission::new(&used,1<<20,&||Ok(()));let mut builder=Builder::default();builder.push(Span::new(2,5),false,&a).unwrap();builder.push(Span::new(8,11),true,&a).unwrap();assert!(builder.push(Span::new(8,11),false,&a).is_err());let facts=builder.finish();assert_eq!(facts.implicit_at_using(Span::new(2,5),&a).unwrap(),Some(false));assert_eq!(facts.implicit_at_using(Span::new(8,11),&a).unwrap(),Some(true));let other_used=crate::SettingChargeCounter::try_new(crate::SettingChargeCounter::root_allocation_bytes()).unwrap();let other=SettingAdmission::new(&other_used,1<<20,&||Ok(()));assert_eq!(facts.implicit_at_using(Span::new(2,5),&other).unwrap_err().kind(),io::ErrorKind::InvalidInput);let alias=facts.clone();drop(facts);assert!(used.load(Ordering::Acquire)>crate::SettingChargeCounter::root_allocation_bytes());drop(alias);assert_eq!(used.load(Ordering::Acquire),crate::SettingChargeCounter::root_allocation_bytes());}
 #[test]fn constructor_fact_first_io_and_quota_refuse_before_ownership_growth(){let used=crate::SettingChargeCounter::try_new(crate::SettingChargeCounter::root_allocation_bytes()).unwrap();let tiny=SettingAdmission::new(&used,crate::SettingChargeCounter::root_allocation_bytes(),&||Ok(()));let mut builder=Builder::default();assert_eq!(builder.push(Span::new(0,3),false,&tiny).unwrap_err().kind(),io::ErrorKind::OutOfMemory);drop(builder);assert_eq!(used.load(Ordering::Acquire),crate::SettingChargeCounter::root_allocation_bytes());let fail=||Err(io::Error::from_raw_os_error(1450));let a=SettingAdmission::new(&used,1<<20,&fail);let mut builder=Builder::default();assert_eq!(builder.push(Span::new(0,3),true,&a).unwrap_err().raw_os_error(),Some(1450));drop(builder);assert_eq!(used.load(Ordering::Acquire),crate::SettingChargeCounter::root_allocation_bytes());}
}
